import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { getById } from "../services/schemeService";
import { Tag, MapPin, FileText, CheckCircle } from "lucide-react";

const SchemeDetails = () => {

    const { id } = useParams();
    const [scheme, setScheme] = useState(null);

    useEffect(() => {
        fetchScheme();
    }, []);

    const fetchScheme = async () => {
        const data = await getById(id);
        setScheme(data);
    };

    if (!scheme) return <h2 style={{ textAlign: "center" }}>Loading...</h2>;

    return (
        <div className="details-container">

            <h2>{scheme.schemeName}</h2>

            <img
                src={process.env.PUBLIC_URL + scheme.image}
                alt={scheme.schemeName}
            />

            <p><Tag size={16} className="icon" /> <strong>Category:</strong> {scheme.category}</p>
            <p><MapPin size={16} className="icon" /> <strong>State:</strong> {scheme.state}</p>
            <p><FileText size={16} className="icon" /> <strong>Description:</strong> {scheme.description}</p>
            <p><CheckCircle size={16} className="icon" /> <strong>Eligibility:</strong> {scheme.eligibility}</p>

            <a
                href={scheme.officialLink}
                target="_blank"
                rel="noreferrer"
                className="btn"
            >
                Apply on Official Website
            </a>

        </div>
    );
};

export default SchemeDetails;
